import { useSyncExternalStore } from "react";
import { Lang, Landmark, LandmarkCategory } from "./types";
import { arabicName } from "./landmarkSearch";
import { categoryLabel } from "./categories";

// Builds the rounds for the games page out of the real landmark dataset.
// Every question, pair and date comes from a landmark record — nothing is
// written by hand here or generated by the AI — so the games can't teach
// something the app's own data doesn't say, and new landmarks join the
// games automatically.
//
// The builders take the landmarks already in the language being shown (see
// localizeLandmarks) plus that language, for the wording around them.

const CATEGORIES: LandmarkCategory[] = ["historical", "archaeological", "natural", "beaches", "urban", "cultural"];

// A landmark's name as the games show it. Arabic names drop an English
// parenthetical some seed records carry (see arabicName).
function nameOf(landmark: Landmark, lang: Lang): string {
  return lang === "en" ? landmark.name : arabicName(landmark.name);
}

export const POINTS_PER_ANSWER = 10;
export const POINTS_PER_LEVEL = 100;

export function levelFor(points: number): number {
  return Math.floor(points / POINTS_PER_LEVEL) + 1;
}

export function shuffle<T>(items: T[]): T[] {
  const result = [...items];
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}

function sample<T>(items: T[], count: number): T[] {
  return shuffle(items).slice(0, count);
}

// The landmarks closest to `focus`, nearest first: itself, then the rest of
// its city, then its region, then everywhere else (in random order within
// each group). On a landmark's own page the games are dealt from the front
// of this list, so they're about that landmark and its surroundings.
export function nearestTo(landmarks: Landmark[], focus: Landmark): Landmark[] {
  const distance = (l: Landmark) => {
    if (l.id === focus.id) return 0;
    if (l.city === focus.city) return 1;
    return l.region === focus.region ? 2 : 3;
  };
  return shuffle(landmarks).sort((a, b) => distance(a) - distance(b));
}

// Landmarks whose name gives away where they are ("كورنيش الخبر", "باب
// مكة") make "which city?" questions either trivial or, when the name
// mentions a different city than the one they're in, misleading.
function withoutCityInName(landmarks: Landmark[]): Landmark[] {
  const cityWords = [...new Set(landmarks.flatMap((l) => l.city.split(/\s+/)))]
    .map((word) => word.replace(/^ال/, ""))
    .filter((word) => word.length >= 3);
  return landmarks.filter((l) => !cityWords.some((word) => l.name.includes(word)));
}

// ---- Memory: match each landmark's photo to its name ----

export interface MemoryCard {
  key: string;
  landmarkId: string;
  kind: "image" | "name";
  name: string;
  image: string;
}

export interface MemoryRound {
  cards: MemoryCard[];
  pairs: number;
}

const MEMORY_PAIRS = 6;

export function buildMemoryRound(landmarks: Landmark[], focus?: Landmark, lang: Lang = "ar"): MemoryRound | null {
  const withImage = landmarks.filter((l) => l.image);
  if (withImage.length < MEMORY_PAIRS) return null;

  const chosen = focus ? nearestTo(withImage, focus).slice(0, MEMORY_PAIRS) : sample(withImage, MEMORY_PAIRS);
  const cards = chosen.flatMap((l): MemoryCard[] => {
    const shared = { landmarkId: l.id, name: nameOf(l, lang), image: l.image as string };
    return [
      { ...shared, key: `${l.id}-image`, kind: "image" },
      { ...shared, key: `${l.id}-name`, kind: "name" },
    ];
  });
  return { cards: shuffle(cards), pairs: MEMORY_PAIRS };
}

// ---- Dated events, read from the landmarks' keyFacts ----

export interface TimelineEvent {
  id: string;
  landmarkId: string;
  year: number;
  text: string;
}

// The keyFacts labels that carry a year, and how to say each in Arabic.
const DATED_FACTS: Record<string, Record<Lang, (name: string) => string>> = {
  Founded: { ar: (name) => `تأسيس ${name}`, en: (name) => `The founding of ${name}` },
  Completed: { ar: (name) => `اكتمال بناء ${name}`, en: (name) => `The completion of ${name}` },
  Opened: { ar: (name) => `افتتاح ${name}`, en: (name) => `The opening of ${name}` },
  "UNESCO listing": {
    ar: (name) => `إدراج ${name} في قائمة التراث العالمي لليونسكو`,
    en: (name) => `${name} is added to the UNESCO World Heritage List`,
  },
};

export function getTimelineEvents(landmarks: Landmark[], lang: Lang = "ar"): TimelineEvent[] {
  const events: TimelineEvent[] = [];
  for (const landmark of landmarks) {
    for (const fact of (landmark.keyFacts || "").split("|")) {
      const separator = fact.indexOf(":");
      if (separator === -1) continue;
      const label = fact.slice(0, separator).trim();
      const year = fact.slice(separator + 1).match(/\b\d{4}\b/);
      if (!DATED_FACTS[label] || !year) continue;
      events.push({
        id: `${landmark.id}-${label}`,
        landmarkId: landmark.id,
        year: Number(year[0]),
        text: DATED_FACTS[label][lang](nameOf(landmark, lang)),
      });
    }
  }
  return events;
}

// ---- Timeline: put events in order, oldest first ----

export interface TimelineRound {
  // In the shuffled order the player starts from.
  events: TimelineEvent[];
}

export const TIMELINE_MIN_EVENTS = 3;
const TIMELINE_MAX_EVENTS = 5;

export function buildTimelineRound(landmarks: Landmark[], focus?: Landmark, lang: Lang = "ar"): TimelineRound | null {
  // Two events in the same year would have no single right order. The
  // focused landmark's events go in last so they win a shared year, and
  // are always part of the round.
  const isOwn = (event: TimelineEvent) => event.landmarkId === focus?.id;
  const all = shuffle(getTimelineEvents(landmarks, lang));
  const byYear = new Map<number, TimelineEvent>();
  for (const event of [...all.filter((e) => !isOwn(e)), ...all.filter(isOwn)]) byYear.set(event.year, event);
  if (byYear.size < TIMELINE_MIN_EVENTS) return null;

  const unique = [...byYear.values()];
  const chosen = [...unique.filter(isOwn), ...shuffle(unique.filter((e) => !isOwn(e)))].slice(0, TIMELINE_MAX_EVENTS);
  const isSorted = (events: TimelineEvent[]) => events.every((e, i) => i === 0 || events[i - 1].year <= e.year);
  let events = shuffle(chosen);
  // Don't hand the player a round that's already solved.
  for (let tries = 0; isSorted(events) && tries < 10; tries++) events = shuffle(chosen);
  return { events };
}

// ---- Quiz: multiple-choice questions ----

export interface QuizQuestion {
  id: string;
  prompt: string;
  image?: string;
  options: string[];
  answer: string;
  landmarkId: string;
}

export interface QuizRound {
  questions: QuizQuestion[];
}

const QUIZ_OPTIONS = 4;
const QUIZ_MIN_LANDMARKS = 8;

function options(answer: string, others: string[]): string[] {
  const distractors = sample([...new Set(others)].filter((o) => o !== answer), QUIZ_OPTIONS - 1);
  return shuffle([answer, ...distractors]);
}

function yearQuestion(event: TimelineEvent, lang: Lang): QuizQuestion {
  // Nearby years, so the wrong answers aren't obviously wrong.
  const nearby = [-12, -9, -6, -4, 4, 6, 9, 12].map((offset) => String(event.year + offset));
  return {
    id: `year-${event.id}`,
    prompt: lang === "en" ? `In which year did this happen: ${event.text}?` : `في أي عام كان ${event.text}؟`,
    options: options(String(event.year), nearby),
    answer: String(event.year),
    landmarkId: event.landmarkId,
  };
}

// Questions about one landmark, answerable from its own page.
function questionsAbout(focus: Landmark, landmarks: Landmark[], events: TimelineEvent[], lang: Lang): QuizQuestion[] {
  const name = nameOf(focus, lang);
  const en = lang === "en";
  return [
    {
      id: `region-${focus.id}`,
      prompt: en ? `Which region is "${name}" in?` : `في أي منطقة يقع معلم «${name}»؟`,
      options: options(focus.region, landmarks.map((l) => l.region)),
      answer: focus.region,
      landmarkId: focus.id,
    },
    {
      id: `category-${focus.id}`,
      prompt: en ? `What kind of landmark is "${name}"?` : `إلى أي نوع من المعالم ينتمي «${name}»؟`,
      options: options(categoryLabel(focus.category, lang), CATEGORIES.map((c) => categoryLabel(c, lang))),
      answer: categoryLabel(focus.category, lang),
      landmarkId: focus.id,
    },
    ...events.filter((e) => e.landmarkId === focus.id).slice(0, 2).map((e) => yearQuestion(e, lang)),
  ];
}

export function buildQuizRound(landmarks: Landmark[], focus?: Landmark, lang: Lang = "ar"): QuizRound | null {
  if (landmarks.length < QUIZ_MIN_LANDMARKS) return null;

  const names = landmarks.map((l) => nameOf(l, lang));
  const cities = landmarks.map((l) => l.city);
  const events = getTimelineEvents(landmarks, lang);
  const others = landmarks.filter((l) => l.id !== focus?.id);

  // On a landmark's page the photos are of its neighbours — its own photo
  // is at the top of the page, which would make the question pointless.
  const withImage = others.filter((l) => l.image);
  const photographedLandmarks = focus ? nearestTo(withImage, focus).slice(0, 3) : sample(withImage, 4);
  const photoQuestions = photographedLandmarks.map((l): QuizQuestion => ({
    id: `photo-${l.id}`,
    prompt: lang === "en" ? "What is this landmark called?" : "ما اسم هذا المعلم؟",
    image: l.image as string,
    options: options(nameOf(l, lang), names),
    answer: nameOf(l, lang),
    landmarkId: l.id,
  }));

  // Not about a landmark already shown in a photo question — its name
  // would be sitting among that question's options.
  const photographed = new Set(photoQuestions.map((q) => q.landmarkId));
  const cityQuestions = sample(
    withoutCityInName(others).filter((l) => !photographed.has(l.id)),
    focus ? 2 : 3
  ).map((l): QuizQuestion => ({
    id: `city-${l.id}`,
    prompt: lang === "en" ? `Which city is "${nameOf(l, lang)}" in?` : `في أي مدينة يقع معلم «${nameOf(l, lang)}»؟`,
    options: options(l.city, cities),
    answer: l.city,
    landmarkId: l.id,
  }));

  if (focus) {
    // The landmark's own questions come first, then the wider ones.
    return { questions: [...questionsAbout(focus, landmarks, events, lang), ...shuffle([...photoQuestions, ...cityQuestions])] };
  }
  return { questions: shuffle([...photoQuestions, ...cityQuestions, ...sample(events, 1).map((e) => yearQuestion(e, lang))]) };
}

// ---- Matching: connect each landmark to its city ----

export interface MatchPair {
  landmarkId: string;
  name: string;
  city: string;
}

export interface MatchRound {
  pairs: MatchPair[];
  // The same cities as `pairs`, in a different order.
  cities: string[];
}

const MATCH_PAIRS = 5;

export function buildMatchRound(landmarks: Landmark[], focus?: Landmark, lang: Lang = "ar"): MatchRound | null {
  // One landmark per city, so every city has exactly one right partner.
  const eligible = shuffle(withoutCityInName(landmarks));
  const byCity = new Map<string, Landmark>();
  for (const landmark of eligible) byCity.set(landmark.city, landmark);
  // The focused landmark represents its city, when its name allows it.
  const own = eligible.find((l) => l.id === focus?.id);
  if (own) byCity.set(own.city, own);
  if (byCity.size < MATCH_PAIRS) return null;

  const rest = sample([...byCity.values()].filter((l) => l !== own), MATCH_PAIRS - (own ? 1 : 0));
  const pairs = shuffle(own ? [own, ...rest] : rest).map((l) => ({
    landmarkId: l.id,
    name: nameOf(l, lang),
    city: l.city,
  }));
  return { pairs, cities: shuffle(pairs.map((p) => p.city)) };
}

// ---- Points, kept in the browser between visits ----

const POINTS_KEY = "smart-tourism-game-points";
const POINTS_EVENT = "smart-tourism-game-points-change";

// Used when the browser refuses localStorage (e.g. private mode), so
// points still count for the current visit.
let fallbackPoints = 0;

function readPoints(): number {
  try {
    return Number(localStorage.getItem(POINTS_KEY)) || 0;
  } catch {
    return fallbackPoints;
  }
}

function subscribeToPoints(onChange: () => void) {
  window.addEventListener("storage", onChange);
  window.addEventListener(POINTS_EVENT, onChange);
  return () => {
    window.removeEventListener("storage", onChange);
    window.removeEventListener(POINTS_EVENT, onChange);
  };
}

export function addGamePoints(points: number) {
  const total = readPoints() + points;
  fallbackPoints = total;
  try {
    localStorage.setItem(POINTS_KEY, String(total));
  } catch {
    // Kept in fallbackPoints for this visit.
  }
  window.dispatchEvent(new Event(POINTS_EVENT));
}

export function useGamePoints(): number {
  return useSyncExternalStore(subscribeToPoints, readPoints, () => 0);
}
